export const ZONE='Europe/Rome';
export function validDateTime(key,time){if(!/^\d{4}-\d{2}-\d{2}$/.test(key)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))return false;const date=new Date(key+'T12:00:00Z');return Number.isFinite(date.getTime())&&date.toISOString().slice(0,10)===key;}
const parts=date=>Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date).map(x=>[x.type,x.value]));
export function dateKey(at=Date.now()){const p=parts(new Date(at));return `${p.year}-${p.month}-${p.day}`;}
export function addDays(key,n){const d=new Date(key+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
export function atRome(key,time){const [y,m,d]=key.split('-').map(Number),[h,min]=time.split(':').map(Number);const target=Date.UTC(y,m-1,d,h,min);let result=target;for(let i=0;i<3;i++){const p=parts(new Date(result));result+=target-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second);}return new Date(result).toISOString();}
export function clock(at){const p=parts(new Date(at));return `${p.hour}:${p.minute}`;}
export function nextDate(weekday,time,now=Date.now()){let key=dateKey(now);for(let i=0;i<8;i++){const day=new Date(key+'T12:00:00Z').getUTCDay();if(day===weekday&&Date.parse(atRome(key,time))>now)return key;key=addDays(key,1);}return key;}
export function times(key,start,end){const startsAt=atRome(key,start),endsAt=atRome(end<=start?addDays(key,1):key,end),meetingAt=new Date(Date.parse(startsAt)-30*60000).toISOString();return {startsAt,endsAt,meetingAt,warmupStartsAt:meetingAt,warmupMinutes:30};}
export function holiday(key){const fixed={'01-01':'newYear','01-06':'epiphany','04-25':'liberation','05-01':'labour','06-02':'republic','08-15':'assumption','11-01':'allSaints','12-08':'immaculate','12-25':'christmas','12-26':'boxing'};if(fixed[key.slice(5)])return fixed[key.slice(5)];const year=+key.slice(0,4);if(year>=2026&&key.slice(5)==='10-04')return 'francis';const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=(h+l-7*m+114)%31+1;const easter=`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;return key===easter?'easter':key===addDays(easter,1)?'easterMonday':null;}
export function occurrenceDates(date,weekly=false,until=date,skip=true){if(!date||!until||until<date)return [];const result=[];for(let key=date,i=0;key<=until&&i<105;key=addDays(key,7),i++){result.push({date:key,holiday:holiday(key),skip:skip&&!!holiday(key)});if(!weekly)break;}return result;}
